pub const V23_5V23_5System = struct {
    config: V23_5V23_5Config,
    pfr_runtime: ?PFRCore.PFRRuntime = null,
    allocator: std.mem.Allocator,
    initialized: bool = false,

    quantum_ir_runtime: ?QuantumIR.QuantumIRRuntime = null,
    antares_runtime: ?AntaresSubgraph.AntaresRuntime = null,
    qlitenet_instance: ?QLiteNet.QLiteNetInstance = null,
    neuropulse_instance: ?NeuroPulseSSM.NeuroPulseInstance = null,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, config: V23_5V23_5Config) !Self {
        var system = Self{
            .config = config,
            .allocator = allocator,
        };

        print("Initializing JAIDE V23_5 System\\n", .{});
        print("Config: memory={}GB, context={}, gpu={}\\n", .{ config.max_memory_gb, config.context_length, config.gpu_acceleration });

        const pfr_config = PFRCore.PFRConfig{
            .max_memory_gb = config.max_memory_gb,
            .gpu_enabled = config.gpu_acceleration,
            .sparsification_enabled = config.sparsification_enabled,
        };
        system.pfr_runtime = try PFRCore.PFRRuntime.init(allocator, pfr_config);

        system.quantum_ir_runtime = try QuantumIR.QuantumIRRuntime.init(allocator);
        system.antares_runtime = try AntaresSubgraph.AntaresRuntime.init(allocator);
        system.qlitenet_instance = try QLiteNet.QLiteNetInstance.init(allocator);
        system.neuropulse_instance = try NeuroPulseSSM.NeuroPulseInstance.init(allocator);

        system.initialized = true;
        print("JAIDE V23_5 system initialization complete\\n", .{});
        return system;
    }

    pub fn deinit(self: *Self) void {
        if (self.pfr_runtime) |*runtime| {
            runtime.deinit();
        }
        if (self.quantum_ir_runtime) |*quantum_ir| {
            quantum_ir.deinit();
        }
        if (self.antares_runtime) |*antares| {
            antares.deinit();
        }
        if (self.qlitenet_instance) |*qlite| {
            qlite.deinit();
        }
        if (self.neuropulse_instance) |*diag| {
            diag.deinit();
        }
        self.initialized = false;
        print("JAIDE V23_5 system deinitialized\\n", .{});
    }

    pub fn testBlitzKriegFutharkIntegration(self: *Self) !void {
        const rows: usize = 4;
        const cols: usize = 4;
        var weights: [rows * cols]i8 = .{ 1, -1, 0, 1, 2, 0, -2, 1, 1, 1, 1, -1, 0, 0, 1, 1 };
        var input: [cols]f32 = .{ 1.0, 2.0, 3.0, 4.0 };
        var output: [rows]f32 = .{ 0, 0, 0, 0 };

        const ok = PFRCore.pfr_execute_blitzkriegfuthark_hyperquant_matvec_sparse(
            &weights, &input, &output, rows, cols, self.config.sparsification_enabled
        );
        if (!ok) return error.BlitzKriegMatVecFailed;

        // Quick sanity check: just ensure something was written.
        var non_zero: usize = 0;
        for (output) |v| if (v != 0) non_zero += 1;
        if (non_zero == 0) return error.BlitzKriegOutputAllZero;
    }

    pub fn testJITIntegration(self: *Self) !void {
        _ = self;
        const result = PFRCore.pfr_jit_execute("hyperquant_optimized_V23_5", true, false);
        if (result <= 0) return error.JITReturnedNonPositive;
    }

    pub fn runInference(self: *Self, prompt: []const u8) ![]const u8 {
        if (!self.initialized) return error.SystemNotInitialized;

        print("Inference: '{s}'\\n", .{prompt});
        const response = try self.executeFullInferencePipeline(prompt);
        print("Response: {s}\\n", .{response});
        return response;
    }

    fn executeFullInferencePipeline(self: *Self, prompt: []const u8) ![]const u8 {
        if (self.pfr_runtime == null) return error.RuntimeNotInitialized;

        var tokens = try self.allocator.alloc(u32, prompt.len);
        defer self.allocator.free(tokens);
        for (prompt, 0..) |ch, i| tokens[i] = @intCast(u32, ch);

        var output = try self.allocator.alloc(u8, prompt.len + 1);
        defer self.allocator.free(output);

        const ok = PFRCore.pfr_execute_inference_V23_5(
            self.pfr_runtime.?,
            tokens,
            tokens.len,
            output,
            output.len,
            self.pfr_runtime.?.config,
        );
        if (!ok) return error.InferenceFailed;

        if (self.neuropulse_instance) |*diag| {
            try diag.pulseDiagnose(output[0..std.mem.len(output)]);
        }

        const result_len = std.mem.indexOfScalar(u8, output, 0) orelse output.len;
        return output[0..result_len];
    }

    pub fn getSystemStats(self: *const Self) void {
        print("\\nSystem Statistics:\\n", .{});
        print(" Memory: {}GB\\n", .{self.config.max_memory_gb});
