const std = @import("std");
const print = std.debug.print;

pub const NeuroPulseInstance = struct {
    allocator: std.mem.Allocator,
    diagnostic_buffer: []u8,
    pulse_state: []f32,
    initialized: bool,

    pub fn init(alloc: std.mem.Allocator) !NeuroPulseInstance {
        var diagnostic_buffer = try alloc.alloc(u8, 4096);
        var pulse_state = try alloc.alloc(f32, 1024);
        @memset(pulse_state, 0.0);

        return NeuroPulseInstance{
            .allocator = alloc,
            .diagnostic_buffer = diagnostic_buffer,
            .pulse_state = pulse_state,
            .initialized = true,
        };
    }

    pub fn deinit(self: *NeuroPulseInstance) void {
        if (self.initialized) {
            self.allocator.free(self.diagnostic_buffer);
            self.allocator.free(self.pulse_state);
            self.initialized = false;
            print("DiagPulse deinitialized\\n", .{});
        }
    }

    pub fn pulseDiagnose(self: *NeuroPulseInstance, output: []const u8) !void {
        if (!self.initialized) return error.DiagPulseNotInitialized;

        var pulse_sum: f32 = 0.0;
        for (self.pulse_state, 0..) |_, i| {
            self.pulse_state[i] = @as(f32, @floatFromInt(i)) * 0.01;
            pulse_sum += self.pulse_state[i];
        }

        const mean = pulse_sum / @as(f32, @floatFromInt(self.pulse_state.len));
        const variance = computeVariance(self.pulse_state);

        const diag_result = try std.fmt.bufPrint(
            self.diagnostic_buffer,
            "Pulse Analysis: Mean={:.3}, Variance={:.3}, OutputLen={}",
            .{ mean, variance, output.len }
        );
        print("Diagnostic Result: {s}\\n", .{diag_result});
    }
};

fn computeVariance(state: []f32) f32 {
    var mean: f32 = 0.0;
    for (state) |v| mean += v;
    mean /= @as(f32, @floatFromInt(state.len));

    var variance: f32 = 0.0;
    for (state) |v| {
        const d = v - mean;
        variance += d * d;
    }
    return variance / @as(f32, @floatFromInt(state.len));
} [1]

