#!/usr/bin/env python3
import ctypes
import json
import logging
import os
from pathlib import Path

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger(__name__)

LIB_REL_PATH = Path(__file__).parent.parent / "pfr" / "lib" / "libpfr_V23_5.so"

class V23_5V23_5PythonBridge:
    def __init__(self) -> None:
        self._lib = None
        if LIB_REL_PATH.exists():
            try:
                self._lib = ctypes.CDLL(str(LIB_REL_PATH))
                logger.info("Loaded native PFR library at %s", LIB_REL_PATH)
            except Exception as e:
                logger.warning("Failed to load native lib: %s", e)
                self._lib = None
        else:
            logger.info("Native lib not found, using pure-Python fallback")

    def generate_text(self, prompt: str, max_length: int = 2048) -> str:
        # Pure-Python fallback: simple identity (truncate)
        if not isinstance(prompt, str):
            prompt = str(prompt)
        return prompt[:max_length]

if __name__ == "__main__":
    bridge = V23_5V23_5PythonBridge()
    out = bridge.generate_text("Smoke test V23_5")
    print(json.dumps({"ok": True, "output": out})) [1]

