#!/usr/bin/env python3
import argparse
import json
import os
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents
ADAPTERS = ROOT / "adapters"
sys.path.insert(0, str(ADAPTERS))

from minimal_python_bridge import V23_5V23_5PythonBridge  # noqa

def maybe_gpu_info():
    try:
        out = subprocess.check_output(["nvidia-smi", "-L"], text=True, timeout=2)
        return out.strip()
    except Exception:
        return "unavailable"

def run(mode: str, iterations: int, duration: int, verbose: bool):
    bridge = V23_5V23_5PythonBridge()
    results = []
    start = time.time()
    for i in range(iterations):
        t0 = time.time()
        text = bridge.generate_text(f"bench-{i}-V23_5")
        t1 = time.time()
        if verbose:
            print(f"iter={i} len={len(text)} ms={(t1 - t0)*1000:.2f}")
        results.append((t1 - t0))
        if time.time() - start > duration:
            break

    stats = {
        "mode": mode,
        "iterations": len(results),
        "p50_ms": float(percentile(results, 50) * 1000) if results else 0.0,
        "p95_ms": float(percentile(results, 95) * 1000) if results else 0.0,
        "gpu": maybe_gpu_info(),
        "timestamp": int(time.time()),
    }

    outdir = ROOT / "scripts" / "benchmark" / "out"
    outdir.mkdir(parents=True, exist_ok=True)
    with open(outdir / "bench.json", "w") as f:
        json.dump(stats, f, indent=2)
    with open(outdir / "bench.csv", "w") as f:
        f.write("iter,ms\\n")
        for i, s in enumerate(results):
            f.write(f"{i},{s*1000:.3f}\\n")

    print(json.dumps(stats))

def percentile(data, p):
    if not data:
        return 0.0
    d = sorted(data)
    k = (len(d)-1) * (p/100)
    f = int(k)
    c = min(f+1, len(d)-1)
    if f == c:
        return d[int(k)]
    return d[f] + (d[c] - d[f]) * (k - f)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mode", default="all")
    ap.add_argument("--iterations", type=int, default=10)
    ap.add_argument("--duration", type=int, default=10)
    ap.add_argument("--verbose", action="store_true")
    args = ap.parse_args()
    run(args.mode, args.iterations, args.duration, args.verbose)

if __name__ == "__main__":
    main() [1]

